<?php require_once __DIR__.'/../config/bootstrap.php'; $u=require_login(); $s=db()->prepare("SELECT e.*,c.titulo,c.categoria,c.carga_horaria,c.imagem,c.preco FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC");$s->execute([$u['id']]);$courses=$s->fetchAll(); $flash=flash(); ?>
<?php layout_header('Área do aluno'); ?><div class="dash-head"><div><span class="eyebrow">ÁREA DO ALUNO</span><h1>Olá, <?=e($u['nome'])?> 👋</h1><p>Acompanhe seus cursos, aulas, progresso e certificados.</p></div><a class="btn ghost" href="<?=e(url('index.php#cursos'))?>">Explorar cursos</a></div><?php if($flash): ?><div class="notice <?=$flash['type']==='error'?'error':'success'?>"><?=e($flash['message'])?></div><?php endif; ?><div class="stat-grid"><div><strong><?=count($courses)?></strong><span>Cursos</span></div><div><strong><?=count(array_filter($courses,fn($x)=>$x['status']==='completed'))?></strong><span>Concluídos</span></div><div><strong><?=count(array_filter($courses,fn($x)=>in_array($x['status'],['active','completed'])))?></strong><span>Ativos</span></div></div><section class="panel"><div class="section-head"><div><span class="eyebrow">MEUS CURSOS</span><h2>Seu aprendizado</h2></div></div><?php if(!$courses): ?><div class="empty"><h3>Você ainda não está matriculado em nenhum curso.</h3><a class="btn" href="<?=e(url('index.php#cursos'))?>">Ver cursos</a></div><?php else: ?><div class="course-list"><?php foreach($courses as $c): $p=course_progress((int)$u['id'],(int)$c['course_id']); ?><article class="course-row"><img src="<?=e(url($c['imagem']?:'assets/img/curso1.svg'))?>"><div class="course-row-info"><small><?=e($c['categoria'])?></small><h3><?=e($c['titulo'])?></h3><div class="progress"><b style="width:<?=$p?>%"></b></div><span><?=$p?>% concluído · <?=e($c['status'])?></span></div><a class="btn" href="<?=e(url('aluno/curso.php?id='.$c['course_id']))?>">Acessar</a></article><?php endforeach; ?></div><?php endif; ?></section><?php layout_footer(); ?>
